insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Residus verts', 'Fleurs, plantes, terre de rempotage, feuilles, rognures de gazon et aiguilles de coniferes vont au bac brun. Au printemps et a l''automne, la Ville fait aussi des collectes de residus verts: en sacs de papier ou en contenant avec couvercle, jamais en sacs de plastique.', null, null), (current_setting('app.id')::bigint, 'en', 'Yard waste', 'Flowers, plants, potting soil, leaves, grass clippings and conifer needles go in the brown bin. In spring and fall the city also runs green-waste collections: in paper bags or a lidded container, never plastic bags.', null, null), (current_setting('app.id')::bigint, 'zh', '园林垃圾', '花草、盆栽土、落叶、剪下的草和针叶放入棕桶。春秋两季市政府另有园林垃圾收集：请用纸袋或带盖容器，不收塑料袋。', null, null);
