insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Branches', 'Les petites branches vont au bac brun: le reglement 1373 fixe un maximum de 1 cm de diametre et 60 cm de long. Du 15 avril au 31 octobre, la Ville ramasse gratuitement sur demande les branches de 4 a 15 cm de diametre et de 3 m au plus. Les branches de 9 pouces et moins sont aussi acceptees gratuitement a l''ecocentre. Buches, troncs, souches et racines ne sont pas ramasses.', null, 'Ramassage sur demande du 15 avril au 31 octobre, delai maximal de 15 jours ouvrables.'), (current_setting('app.id')::bigint, 'en', 'Branches', 'Small branches go in the brown bin: regulation 1373 sets a maximum of 1 cm across and 60 cm long. From 15 April to 31 October the city collects branches 4 to 15 cm across and up to 3 m long, free, on request. Branches of 9 inches across or less are also free at the ecocentre. Logs, trunks, stumps and roots are not collected.', null, 'Pickup on request from 15 April to 31 October, within 15 working days.'), (current_setting('app.id')::bigint, 'zh', '树枝', '小树枝放入棕桶：1373 号条例规定直径不超过 1 厘米、长度不超过 60 厘米。4 月 15 日至 10 月 31 日，市政府可应申请免费收集直径 4-15 厘米、长度不超过 3 米的树枝。直径 9 英寸以内的树枝也可免费送到生态中心。原木、树干、树桩和树根不收。', null, '4 月 15 日至 10 月 31 日可申请上门收集，最长 15 个工作日内完成。');
