insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Mouchoirs, serviettes et essuie-tout', 'Les serviettes de table, le papier essuie-tout et les papiers mouchoirs vont au bac brun. Un essuie-tout souille de produits de nettoyage va au bac noir.', null, null), (current_setting('app.id')::bigint, 'en', 'Tissues, napkins and paper towels', 'Napkins, paper towels and tissues go in the brown bin. A paper towel soiled with cleaning products goes in the black bin.', null, null), (current_setting('app.id')::bigint, 'zh', '纸巾、餐巾和厨房纸', '餐巾、厨房纸和纸巾放入棕桶。沾了清洁剂的厨房纸放入黑桶。', null, null);
