insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Papiers et cartons souilles d aliments', 'Les papiers et cartons souilles par des aliments vont au bac brun: assiettes de carton, boites de pizza, papier qui a servi a emballer des aliments.', null, null), (current_setting('app.id')::bigint, 'en', 'Food-soiled paper and cardboard', 'Paper and cardboard soiled by food go in the brown bin: paper plates, pizza boxes, paper used to wrap food.', null, null), (current_setting('app.id')::bigint, 'zh', '沾有食物的纸和纸板', '沾有食物的纸和纸板放入棕桶：纸盘、披萨盒、包过食物的纸。', null, null);
