insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Sable et terre', 'De petites quantites de sable et de terre vont au bac brun. Pour de grandes quantites, la terre et les deblais vont a l''ecocentre; ils sont refuses a la collecte des encombrants.', null, null), (current_setting('app.id')::bigint, 'en', 'Sand and soil', 'Small amounts of sand and soil go in the brown bin. Large amounts of soil and fill go to the ecocentre; the bulky pickup refuses them.', null, null), (current_setting('app.id')::bigint, 'zh', '沙子和泥土', '少量沙子和泥土放入棕桶。大量泥土和渣土送到生态中心；大件垃圾收集不收。', null, null);
