insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Sacs compostables ou biodegradables', 'Les sacs de plastique, meme biodegradables ou compostables, sont interdits dans le bac brun: seuls les sacs de papier y sont acceptes. Le bac bleu exclut aussi les plastiques degradables. Ils vont donc au bac noir.', null, null), (current_setting('app.id')::bigint, 'en', 'Compostable or biodegradable bags', 'Plastic bags, even biodegradable or compostable ones, are banned from the brown bin: only paper bags are accepted there. The blue bin excludes degradable plastics too. So they go in the black bin.', null, null), (current_setting('app.id')::bigint, 'zh', '可堆肥或可降解塑料袋', '塑料袋即使是可降解或可堆肥的，也不能放入棕桶：棕桶只接受纸袋。蓝桶同样不收可降解塑料。因此请放入黑桶。', null, null);
