insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Boites de carton', 'Les boites de carton ondule, plat ou lamine et les rouleaux de carton vont au bac bleu. Le carton n''est plus accepte a la collecte des encombrants; deux collectes de surplus de carton ont lieu chaque annee.', null, null), (current_setting('app.id')::bigint, 'en', 'Cardboard boxes', 'Corrugated, flat or laminated cardboard boxes and cardboard tubes go in the blue bin. The bulky pickup no longer takes cardboard; there are two cardboard surplus collections a year.', null, null), (current_setting('app.id')::bigint, 'zh', '纸箱', '瓦楞纸箱、平板或覆膜纸盒以及纸筒放入蓝桶。大件垃圾收集不再收纸板；每年有两次纸板加量收集。', null, null);
