insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Bouteilles et contenants de plastique', 'Les bouteilles, contenants et emballages de plastique no 1, 2, 3, 4 et 5 vont au bac bleu: aliments, boissons, cosmetiques, hygiene et produits d''entretien.', null, null), (current_setting('app.id')::bigint, 'en', 'Plastic bottles and containers', 'Plastic bottles, containers and packaging marked 1, 2, 3, 4 or 5 go in the blue bin: food, drinks, cosmetics, toiletries and cleaning products.', null, null), (current_setting('app.id')::bigint, 'zh', '塑料瓶和塑料容器', '标有 1、2、3、4、5 号的塑料瓶、容器和包装放入蓝桶：食品、饮料、化妆品、个人护理和清洁用品均可。', null, null);
