insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Contenants alimentaires en styromousse', 'Les emballages et contenants alimentaires en polystyrene (no 6), expanse ou rigide, vont au bac bleu a Sainte-Therese: barquettes de viande, verres a cafe, contenants de mets a emporter. L''emballage de protection en styromousse, lui, va a l''ecocentre.', null, null), (current_setting('app.id')::bigint, 'en', 'Styrofoam food containers', 'Polystyrene (number 6) food packaging and containers, foam or rigid, go in the blue bin in Sainte-Therese: meat trays, coffee cups, take-out containers. Protective foam packaging goes to the ecocentre instead.', null, null), (current_setting('app.id')::bigint, 'zh', '泡沫餐盒', '在 Sainte-Therese，6 号聚苯乙烯食品包装和容器（发泡或硬质）放入蓝桶：肉托盘、咖啡杯、外卖餐盒。保护用泡沫包装则送到生态中心。', null, null);
