insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Aerosols', 'Les contenants sous pression (aerosols) sont exclus du bac bleu. Ce sont des residus domestiques dangereux: apportez-les a l''ecocentre.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (current_setting('app.id')::bigint, 'en', 'Aerosol cans', 'Pressurised containers (aerosols) are excluded from the blue bin. They are household hazardous waste: take them to the ecocentre.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of residence required. Closed from 21 December 2026 to 7 January 2027.'), (current_setting('app.id')::bigint, 'zh', '气雾罐', '压力容器（气雾罐）不能放入蓝桶。它们属于家庭危险废物，请送到生态中心。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
