insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Peinture et solvants', 'La peinture, les solvants, les acides et les nettoyants sont des residus domestiques dangereux: apportez-les a l''ecocentre. Jamais au bac noir.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (current_setting('app.id')::bigint, 'en', 'Paint and solvents', 'Paint, solvents, acids and cleaners are household hazardous waste: take them to the ecocentre. Never in the black bin.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of residence required. Closed from 21 December 2026 to 7 January 2027.'), (current_setting('app.id')::bigint, 'zh', '油漆和溶剂', '油漆、溶剂、酸碱和清洁剂属于家庭危险废物，请送到生态中心，切勿放入黑桶。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
