insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Piles et batteries', 'Les piles et batteries vont a l''ecocentre, comme les produits qui fonctionnent avec des piles. Regroupez les piles au lithium dans un sac, separees des autres.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (current_setting('app.id')::bigint, 'en', 'Batteries', 'Batteries go to the ecocentre, as do battery-powered products. Put lithium batteries in a bag of their own, apart from the others.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of residence required. Closed from 21 December 2026 to 7 January 2027.'), (current_setting('app.id')::bigint, 'zh', '电池', '电池以及用电池驱动的产品送到生态中心。锂电池请单独装袋，与其他电池分开。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
