insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Huile de cuisson usagee', 'L''huile de cuisson usagee va a l''ecocentre, avec l''huile a moteur. Ne la versez pas dans le bac brun.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (current_setting('app.id')::bigint, 'en', 'Used cooking oil', 'Used cooking oil goes to the ecocentre, with motor oil. Do not pour it into the brown bin.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of residence required. Closed from 21 December 2026 to 7 January 2027.'), (current_setting('app.id')::bigint, 'zh', '废食用油', '废食用油和机油一样送到生态中心，不要倒入棕桶。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
