insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Materiaux de construction et renovation', 'Depuis 2026, les materiaux de construction, renovation et demolition ne sont plus acceptes a la collecte des encombrants. Ils sont acceptes gratuitement a l''ecocentre jusqu''a 10 metres cubes par annee par adresse.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (current_setting('app.id')::bigint, 'en', 'Construction and renovation debris', 'Since 2026, construction, renovation and demolition materials are no longer taken by the bulky pickup. The ecocentre accepts them free, up to 10 cubic metres a year per address.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of residence required. Closed from 21 December 2026 to 7 January 2027.'), (current_setting('app.id')::bigint, 'zh', '建筑和装修垃圾', '自 2026 年起，大件垃圾收集不再收建筑、装修和拆除材料。生态中心免费接收，每个地址每年最多 10 立方米。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
