insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Styromousse de protection', 'Le styromousse de protection (emballage d''appareils, caissettes de vegetaux) est exclu du bac bleu: nettoye et trie, il va a l''ecocentre. Les contenants alimentaires en styromousse, eux, vont au bac bleu.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Vendredi 12 h a 19 h; samedi et dimanche 9 h a 18 h. Preuve de residence exigee. Ferme du 21 decembre 2026 au 7 janvier 2027.'), (current_setting('app.id')::bigint, 'en', 'Protective styrofoam packaging', 'Protective foam (appliance packaging, plant trays) is excluded from the blue bin: cleaned and sorted, it goes to the ecocentre. Foam food containers go in the blue bin.', 'Ecocentre, 105 rue Blanchard, Sainte-Therese', 'Friday noon to 7 p.m.; Saturday and Sunday 9 a.m. to 6 p.m. Proof of residence required. Closed from 21 December 2026 to 7 January 2027.'), (current_setting('app.id')::bigint, 'zh', '保护用泡沫包装', '保护用泡沫（电器包装、育苗托盘）不能放入蓝桶，清洁分类后送到生态中心。泡沫食品容器则放入蓝桶。', '生态中心，105 rue Blanchard, Sainte-Therese', '周五 12:00-19:00；周六、周日 9:00-18:00。需出示居住证明。2026 年 12 月 21 日至 2027 年 1 月 7 日关闭。');
