insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Encombrants', 'Les encombrants sont ramasses le premier lundi du mois, partout: meubles, matelas, fauteuils, electromenagers non refrigerants, chauffe-eau, filtres de piscine sans le sable. Maximum 2,5 m et 25 kg par objet. Refuses: carton, materiaux de construction, electroniques, appareils refrigerants, pneus, residus dangereux.', null, 'Premier lundi du mois. En bordure de rue des 18 h la veille ou avant 7 h le jour meme.'), (current_setting('app.id')::bigint, 'en', 'Bulky items', 'Bulky items are picked up on the first Monday of the month, everywhere: furniture, mattresses, armchairs, non-refrigerating appliances, water heaters, pool filters without sand. At most 2.5 m and 25 kg per item. Refused: cardboard, construction materials, electronics, refrigerating appliances, tires, hazardous waste.', null, 'First Monday of the month. At the curb from 6 p.m. the day before or by 7 a.m. that day.'), (current_setting('app.id')::bigint, 'zh', '大件垃圾', '大件垃圾每月第一个周一全市收集：家具、床垫、沙发、非制冷家电、热水器、去沙的泳池过滤器。每件最长 2.5 米、最重 25 公斤。不收：纸板、建筑材料、电子产品、制冷电器、轮胎、危险废物。', null, '每月第一个周一。前一天 18 点后或当天 7 点前放到路边。');
