insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Refrigerateur, congelateur et climatiseur', 'Les gros appareils refrigerants ne sont plus ramasses avec les encombrants. La Ville les ramasse gratuitement a domicile sur demande (en ligne, par courriel a travauxpublics@sainte-therese.ca ou au 450 434-1440, poste 2100), dans un delai de 3 jours ouvrables. Vous pouvez aussi les apporter a l''ecocentre.', null, null), (current_setting('app.id')::bigint, 'en', 'Fridge, freezer and air conditioner', 'Large refrigerating appliances are no longer picked up with bulky items. The city collects them from your home for free on request (online, by email to travauxpublics@sainte-therese.ca or at 450 434-1440, ext. 2100), within 3 working days. You can also take them to the ecocentre.', null, null), (current_setting('app.id')::bigint, 'zh', '冰箱、冰柜和空调', '大型制冷电器不再随大件垃圾收集。市政府可应申请免费上门收取（网上申请、发邮件至 travauxpublics@sainte-therese.ca 或致电 450 434-1440 转 2100），3 个工作日内完成。也可自行送到生态中心。', null, null);
