insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Sapins de Noel', 'Les sapins naturels sont ramasses le 12 janvier 2027, sur inscription seulement: en ligne (option collecte de sapin) ou au 450 434-1440, poste 2100, au plus tard le 10 janvier a 7 h. Sans aucune decoration, en bordure de rue, la partie coupee face a la rue.', null, '12 janvier 2027, sur inscription au plus tard le 10 janvier a 7 h.'), (current_setting('app.id')::bigint, 'en', 'Christmas trees', 'Natural trees are collected on 12 January 2027, by registration only: online (Christmas tree option) or at 450 434-1440, ext. 2100, by 10 January at 7 a.m. With every decoration removed, at the curb, cut end facing the street.', null, '12 January 2027, register by 10 January at 7 a.m.'), (current_setting('app.id')::bigint, 'zh', '圣诞树', '天然圣诞树于 2027 年 1 月 12 日收集，仅限登记：网上申请（选择圣诞树收集）或致电 450 434-1440 转 2100，截止 1 月 10 日早上 7 点。请去掉所有装饰，放在路边，切口朝向街道。', null, '2027 年 1 月 12 日，须在 1 月 10 日早上 7 点前登记。');
