insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Retailles de cedre', 'Du 1er mai au 31 octobre, Arbressence ramasse gratuitement les retailles de cedre: reservez en ligne sur arbressence.ca. Retailles d''au plus un pouce de diametre et trois pieds de long; pas de branches.', null, 'Du 1er mai au 31 octobre, ramassage dans les 48 heures.'), (current_setting('app.id')::bigint, 'en', 'Cedar trimmings', 'From 1 May to 31 October, Arbressence collects cedar trimmings for free: book online at arbressence.ca. Trimmings at most one inch across and three feet long; no branches.', null, '1 May to 31 October, collected within 48 hours.'), (current_setting('app.id')::bigint, 'zh', '雪松修剪枝叶', '5 月 1 日至 10 月 31 日，Arbressence 免费收集雪松修剪枝叶：在 arbressence.ca 网上预约。直径不超过 1 英寸、长度不超过 3 英尺；不收树枝。', null, '5 月 1 日至 10 月 31 日，48 小时内收集。');
